SELECT AR.OT_LIMIT_NO, HR.PERSON_ID, HR.EMPID, HR.LOCAL_NAME, HR.DEPTNO, GET_DEPT_NAME(HR.DEPTNO, #{lang, jdbcType=VARCHAR}) AS DEPT_NAME, TO_CHAR(TO_DATE(AR.AR_MONTH_STR, 'YYYYMM'), 'MM/YYYY') AS AR_MONTH_STR, AR.OT_LIMIT_MONTH, AR.OT_LIMIT_YEAR, GET_AR_OT_TOTAIL(TO_CHAR(TO_DATE(AR.AR_MONTH_STR, 'YYYYMM'), 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, HR.PERSON_ID, '2011') AS OT_TOTAIL, GET_AR_OT_TOTAIL(TO_CHAR(TO_DATE(AR.AR_MONTH_STR, 'YYYYMM'), 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, HR.PERSON_ID, '31') AS OT_TOTAIL_MONTH, GET_AR_OT_TOTAIL(TO_CHAR(TO_DATE(AR.AR_MONTH_STR, 'YYYYMM'), 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, HR.PERSON_ID, '311') AS WEEKDAY_OT_TOTAIL, GET_AR_OT_TOTAIL(TO_CHAR(TO_DATE(AR.AR_MONTH_STR, 'YYYYMM'), 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, HR.PERSON_ID, '312') AS SATURDAY_OT_TOTAIL, GET_AR_OT_TOTAIL(TO_CHAR(TO_DATE(AR.AR_MONTH_STR, 'YYYYMM'), 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, HR.PERSON_ID, '314') AS WEEKEND_OT_TOTAIL, GET_AR_OT_TOTAIL(TO_CHAR(TO_DATE(AR.AR_MONTH_STR, 'YYYYMM'), 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, HR.PERSON_ID, '315') AS HOILDAY_OT_TOTAIL, GET_EMPID(AR.UPDATED_BY) AS UPDATED_BY_ID, GET_LOCAL_NAME_BY_PERSONID(AR.UPDATED_BY, #{cpnyId, jdbcType=VARCHAR}) AS UPDATE_LOCAL_NAME, TO_CHAR(AR.UPDATE_DATE, 'DD/MM/YYYY HH24:MI') AS UPDATE_DATE FROM AR_OVERTIME_LIMIT AR JOIN HR_EMPLOYEE HR ON AR.PERSON_ID = HR.PERSON_ID WHERE HR.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND AR.PERSON_ID NOT LIKE '111111%' AND AR.ACTIVITY = '1'
AND INSTR(',' || #{deptNos, jdbcType=VARCHAR} || ',', ',' || HR.DEPTNO || ',') > 0
AND ( HR.EMPID LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR CONVERTTOUNSIGN(UPPER(HR.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%' OR UPPER(HR.ENGLISH_NAME) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%' )
AND HR.POST_FAMILY = #{postFamily, jdbcType=VARCHAR}
AND AR.AR_MONTH_STR BETWEEN #{startMonth, jdbcType=VARCHAR} AND #{endMonth, jdbcType=VARCHAR}
AND AR.OT_LIMIT_MONTH = #{filterOtLimitMonth, jdbcType=VARCHAR}
AND AR.OT_LIMIT_YEAR = #{filterOtLimitYear, jdbcType=VARCHAR}
AND GET_AR_OT_TOTAIL(TO_CHAR(SYSDATE, 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, HR.PERSON_ID, '30') >= TO_NUMBER(#{minOtHours, jdbcType=VARCHAR})
ORDER BY HR.PERSON_ID ASC

mapper.update:
UPDATE AR_OVERTIME_LIMIT AR
   SET AR.UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       AR.UPDATE_DATE = SYSDATE,
       AR.UPDATED_IP = #{adminIP, jdbcType=VARCHAR}

       , AR.OT_LIMIT_MONTH = #{otLimitMonth, jdbcType=VARCHAR}


       , AR.OT_LIMIT_YEAR = #{otLimitYear, jdbcType=VARCHAR}

 WHERE AR.OT_LIMIT_NO = #{otLimitNo, jdbcType=VARCHAR}

UPDATE HR_EMPLOYEE HR
   SET HR.UPDATED_BY_OT_LIMIT = #{adminID, jdbcType=VARCHAR},
       HR.UPDATE_DATE_OT_LIMIT = SYSDATE,
       HR.OT_LIMIT = #{otLimit, jdbcType=INTEGER},
       HR.OT_LIMIT_100 = #{otLimit100, jdbcType=INTEGER}
 WHERE HR.PERSON_ID = #{personId, jdbcType=VARCHAR}
   AND HR.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
